/// <summary>
/// Initializes the <c>TmpInventTransfer</c> record.
/// </summary>
/// <param name = "_inventTransferJour">
/// The table buffer of the <c>InventTransferJour</c>.
/// </param>
/// <param name = "_inventTransferJourLine">
/// The table buffer of the <c>InventTransferJourLine</c>.
/// </param>
/// <param name = "_inventDim">
/// The table buffer of the <c>InventDim</c>.
/// </param>
/// <param name = "_companyinfo">
/// The table buffer of the <c>CompanyInfo</c>.
/// </param>
/// <param name = "_inventTransferTable">
/// The table buffer of the <c>InventTransferTable</c>.
/// </param>
/// <param name = "_inventTransferLine">
/// The table buffer of the <c>InventTransferLine</c>.
/// </param>
protected void initTmpInventTransfer(   InventTransferJour      _inventTransferJour,
                                        InventTransferJourLine  _inventTransferJourLine,
                                        InventDim               _inventDim,
                                        CompanyInfo             _companyinfo,
                                        InventTransferTable     _inventTransferTable,
                                        InventTransferLine      _inventTransferLine     )
{
    InventTransferLine  locInventTransferLine;

    next initTmpInventTransfer( _inventTransferJour,
                                _inventTransferJourLine,
                                _inventDim,
                                _companyinfo,
                                _inventTransferTable,
                                _inventTransferLine     );


    locInventTransferLine = _inventTransferJourLine.inventTransferLine();

    if(locInventTransferLine.RecId)
    {
        tmpInventTransfer.KCS_SOCPickingReleaseIndicator = locInventTransferLine.KCS_SOCPickingReleaseIndicator;
        tmpInventTransfer.AVAItemSet                    = locInventTransferLine.AVAItemSet;
        tmpInventTransfer.AVAItemSetExpanded            = locInventTransferLine.AVAItemSetExpanded;
        tmpInventTransfer.AVAItemSetComponent           = locInventTransferLine.AVAItemSetComponent;
        tmpInventTransfer.AVAItemSetParent              = locInventTransferLine.AVAItemSetParent;
        tmpInventTransfer.AVAItemSetCompQtyPerSerie     = locInventTransferLine.AVAItemSetCompQtyPerSerie;
        tmpInventTransfer.AVAItemSetSerie               = locInventTransferLine.AVAItemSetSerie;
        tmpInventTransfer.AVAProdSchedDate              = locInventTransferLine.AVAProdSchedDate;
    }
}
